"legend":{a:[{tr:"i. efsane",ex:"According to local legend, a hidden treasure lies buried somewhere beneath the ancient castle.",exTr:"Yerel efsaneye göre, antik kalenin bir yerinde gizli bir hazine gömülüdür."},{tr:"i. (harita/şekil) açıklama notu, lejant",ex:"Readers should check the map's legend carefully before trying to identify each symbol's meaning.",exTr:"Okuyucular, her sembolün anlamını belirlemeye çalışmadan önce haritanın lejantını dikkatle kontrol etmelidir."}],kl:[{en:"according to legend",tr:"efsaneye göre"},{en:"a living legend",tr:"yaşayan efsane"}]},
"minimum":{a:[{tr:"s. asgari, en az",ex:"Factory workers are legally entitled to a minimum wage that reflects the cost of living.",exTr:"Fabrika işçileri, yaşam maliyetini yansıtan asgari bir ücrete yasal olarak hak kazanır."},{tr:"i. asgari düzey, en az miktar",ex:"Costs must be kept to a minimum if the project is to remain viable.",exTr:"Projenin sürdürülebilir kalması için maliyetler asgaride tutulmalıdır."}],kl:[{en:"keep sth to a minimum",tr:"bir şeyi en aza indirmek"},{en:"the minimum wage",tr:"asgari ücret"},{en:"a minimum requirement",tr:"asgari koşul"}]},
"minutes":{a:[{tr:"i. (toplantı) tutanak, zabıt",ex:"The secretary carefully recorded the minutes of the board meeting for future reference.",exTr:"Sekreter, ileride başvurmak üzere yönetim kurulu toplantısının tutanağını dikkatle kaydetti."},{tr:"i. dakikalar (zaman birimi)",ex:"The marathon's final section took the exhausted runners nearly forty minutes to complete.",exTr:"Maratonun son bölümünü tamamlamak, bitkin koşuculara neredeyse kırk dakika sürdü."}],kl:[{en:"the minutes of the meeting",tr:"toplantı tutanağı"},{en:"take the minutes",tr:"toplantı tutanağı tutmak"}]},
