"politician":{a:[{tr:"i. politikacı, siyasetçi",ex:"A prominent politician proposed a new bill aimed at reducing carbon emissions from heavy industry.",exTr:"Tanınmış bir politikacı, ağır sanayiden kaynaklanan karbon emisyonlarını azaltmayı amaçlayan yeni bir yasa tasarısı önerdi."}],kl:[{en:"a leading politician",tr:"önde gelen bir siyasetçi"},{en:"a corrupt politician",tr:"yozlaşmış bir siyasetçi"}]},
"reporter":{a:[{tr:"i. muhabir, gazeteci, haber sunucusu",ex:"A local reporter uncovered evidence that the factory had been dumping chemical waste into the river for years.",exTr:"Yerel bir muhabir, fabrikanın yıllardır nehre kimyasal atık boşalttığına dair kanıt buldu."}]},
"satisfaction":{a:[{tr:"i. memnuniyet, tatmin",ex:"Employee satisfaction tends to improve significantly when workers are given greater flexibility over their schedules.",exTr:"Çalışanlara programları üzerinde daha fazla esneklik tanındığında, çalışan memnuniyeti genellikle belirgin biçimde artar."},{tr:"i. (hukuk) tazmin, giderim",ex:"The court ordered the company to pay full satisfaction for the damages caused by the oil spill.",exTr:"Mahkeme, şirketin petrol sızıntısının neden olduğu zararlar için tam tazmin ödemesine hükmetti."}],kl:[{en:"with satisfaction",tr:"memnuniyetle, hoşnutlukla"},{en:"job satisfaction",tr:"iş doyumu"},{en:"customer satisfaction",tr:"müşteri memnuniyeti"}]},
"significance":{a:[{tr:"i. önem; anlam",ex:"Archaeologists debated the historical significance of the newly discovered inscriptions for several months.",exTr:"Arkeologlar, yeni keşfedilen yazıtların tarihsel önemini aylarca tartıştı."}],kl:[{en:"the significance of sth",tr:"bir şeyin önemi"},{en:"attach significance to sth",tr:"bir şeye önem atfetmek"},{en:"of great significance",tr:"büyük önem taşıyan"}]},
"studying":{a:[{tr:"i. (ders) çalışma, inceleme; öğrenim",ex:"Many students find that studying in short, focused sessions improves memory retention more than long sessions.",exTr:"Birçok öğrenci, kısa ve odaklanmış oturumlar hâlinde çalışmanın belleği uzun oturumlardan daha iyi pekiştirdiğini görüyor."}],kl:[{en:"worth studying",tr:"incelenmeye değer"},{en:"spend hours studying",tr:"saatlerce ders çalışmak"}]},
"violent":{a:[{tr:"s. şiddetli, sert; şiddet içeren",ex:"A violent storm swept through the coastal town, destroying dozens of fishing boats overnight.",exTr:"Şiddetli bir fırtına kıyı kasabasını vurarak bir gecede düzinelerce balıkçı teknesini yok etti."}],kl:[{en:"a violent crime",tr:"şiddet suçu"},{en:"violent behaviour",tr:"şiddet içeren davranış"},{en:"a violent storm",tr:"şiddetli fırtına"}]},
"acceptable":{a:[{tr:"s. kabul edilebilir",ex:"Regulators determined that the factory's emission levels were no longer acceptable under updated environmental standards.",exTr:"Düzenleyici kurumlar, fabrikanın emisyon düzeylerinin güncellenmiş çevre standartlarına göre artık kabul edilebilir olmadığını belirledi."}],kl:[{en:"acceptable to sb",tr:"biri için kabul edilebilir"},{en:"socially acceptable",tr:"toplumca kabul gören"},{en:"an acceptable level",tr:"kabul edilebilir düzey"}]},
